export type IconName = keyof typeof iconMap;
export const iconNames = Object.keys(iconMap) as Array<IconName>;

export const iconSizes = ["xxs", "xs", "s", "m", "l", "xl", "xxl"] as const;

export type IconProps = {
  /** Key in `iconMap`. Unknown names render nothing */
  name: IconName;
  /** Maps to the `--foundation-font-size-{size}` token. Without it the icon follows the surrounding font size */
  size?: (typeof iconSizes)[number];
  /** Applied on the svg. Set `color` or `font-size` here to override the defaults */
  className?: string;
  "data-testid"?: string;
};

export const Icon = ({ name, size, className, "data-testid": dataTestId }: IconProps) => {
  if (name === "loading") {
    const Loader = iconMap[name];
    return (
      <Loader
        data-size={size}
        color="inherit"
        className={multipleClassNames(styles.muiIcon, className)}
        size="var(--icon-font-size, 1.1em)" // Remember to sync this with the LESS-file for `styles.muiIcon`
        data-testid={dataTestId}
      />
    );
  }

  const IconComponent = iconMap[name];
  if (!IconComponent) return null;
  return (
    <IconComponent
      data-size={size}
      className={multipleClassNames(styles.muiIcon, className)}
      // @ts-expect-error We intentionally pass "none" to fontSize so that it doesn't set a font-size that can't be overridden using CSS
      fontSize="none"
      data-testid={dataTestId}
    />
  );
};
