import { PropsWithChildren, createContext, useContext } from "react";
import { OpeningHoursItem, ProductInformationResponseItem } from "@parksandresorts/webapiproxy-types";
import { ProductBlockFragment } from "../types";

const allowedPaymentProviders = ["Klarna", "Nets"] as const;
type AllowedPaymentProviders = (typeof allowedPaymentProviders)[number];

export type StaticConfigContextType = {
  eCommerce: {
    preferredPaymentProvider: AllowedPaymentProviders;
    /** The page to send the guest to when they want to pay for their cart */
    shopServicePaymentSlug: string;
    /** The page to redirect back to after a completed purchase */
    shopServiceConfirmationSlug: string;
    /**This is needed by the new ShopService/Klarna. Unclear what it is, but we believe its to link to our "tickets" */
    shopServiceCheckoutSlug: string;
    /** CMS-configured link to send the guest to when they want to continue shopping instead of checking out */
    continueShoppingLink?: { internalLink: { slug: string }; title: string };
  };
  products: {
    glkProducts: Array<ProductInformationResponseItem>;
    contentfulProducts: Array<ProductBlockFragment>;
  };
  features?: {
    /** Enable the new attraction schedule endpoint for ride opening hours.
     *  Default: false. Enable per environment as data quality improves. */
    attractionScheduleEndpoint?: boolean;
  };
  /** pre-fetched result from the opening-hours endpoint, allowing us to access the data during build-time (though possibly stale) */
  openingHours?: Array<OpeningHoursItem>;
};
const StaticConfigContext = createContext<StaticConfigContextType | null>(null);

type ContextProps = PropsWithChildren<{ data: StaticConfigContextType }>;

export const StaticConfigContextProvider = ({ children, data }: ContextProps) => {
  // This check might seem unnecessary, but we are being overly defensive here to ensure we use a valid payment provider.
  // And this is because we cannot be 100% certain we get valid data from the Contentful.
  if (
    typeof data.eCommerce?.preferredPaymentProvider !== "string" ||
    !allowedPaymentProviders.includes(data.eCommerce.preferredPaymentProvider)
  ) {
    const unsupported = data.eCommerce.preferredPaymentProvider;
    data.eCommerce.preferredPaymentProvider = "Klarna";

    console.warn(
      `preferredPaymentProvider "${unsupported}" is not supported. Falling back to "${data.eCommerce.preferredPaymentProvider}".`,
    );
  }
  return <StaticConfigContext.Provider value={data}>{children}</StaticConfigContext.Provider>;
};

export const useStaticConfigContext = () => {
  const context = useContext(StaticConfigContext);

  if (!context) {
    throw new Error("useStaticConfigContext must be used within an StaticConfigContextProvider");
  }

  return context;
};
