// @ts-strict-ignore
import get from "lodash-es/get";

export const extract = <T>(object: unknown, path: string, defaultValue: T = undefined): T => {
  const value = get(object, path, defaultValue);
  return value === null ? defaultValue : value;
};

export const exhaustiveCheck = (_param: never) => {
  throw new Error("should not reach here"); //https://stackoverflow.com/a/39419171
};

/**
 * Used to throw errors inline, which is useful for conditional expressions and when using the `||` or `??` operator.
 */
export function throwError(...args: Parameters<ErrorConstructor>): never {
  throw new Error(...args);
}

/** A wrapper around the Map constructor that coerces the type of the returned map to be ReadonlyMap */
export function readonlyMap<K, V>(...args: ConstructorParameters<typeof Map<K, V>>): ReadonlyMap<K, V> {
  return new Map<K, V>(...args);
}
