import { useCallback, useEffect, useState } from "react";
import { motion } from "framer-motion";
import { AnimatePresence } from "framer-motion";
import { Notification } from "@/core/components/primitives/notification/notification";
import styles from "./notification-center.module.less";
import { TIME_PERSISTENT } from "./constants/time-types";
import { ADD_TO_CART_NOTIFICATION } from "./constants/notification-types";
import { extract } from "@/core/helpers/object-helper";
import AddToCartNotification from "@/core/components/modules/add-to-cart-nofication/add-to-cart-notification";
import { INotification } from "@/core/types/notifications/notifications";

const NOTIFICATION_DEFAULT_TIME = 5;

type INotificationCenterProps = {
  notifications: Array<INotification>;
  removeNotification: CallableFunction;
  setValue: (value: any, callback: any) => void;
};

const NotificationCenter = ({ notifications, removeNotification, setValue }: INotificationCenterProps) => {
  const [currentNotificationsIds, setCurrentNotificationsIds] = useState<Array<string>>([]);

  const onRemoveNotification = useCallback(
    (id: string) => {
      setCurrentNotificationsIds((prevNotifications) => {
        const foundId = prevNotifications.includes(id);

        if (foundId) {
          removeNotification(id);
          return prevNotifications.filter((removeId) => removeId !== id);
        }
        return prevNotifications;
      });
    },
    [removeNotification],
  );

  useEffect(() => {
    for (const notification of notifications) {
      const foundNotification = currentNotificationsIds.find((noti) => noti === notification.id) ? true : false;

      if (!foundNotification) {
        const newState = [...currentNotificationsIds];
        newState.push(notification.id);

        setCurrentNotificationsIds(newState);

        if (notification.displayTime !== TIME_PERSISTENT) {
          const notificationDisplayTime = extract<number>(notification, "displayTime");
          const timeOutTime = notificationDisplayTime
            ? notificationDisplayTime * 1000
            : NOTIFICATION_DEFAULT_TIME * 1000;
          setTimeout(() => onRemoveNotification(notification.id), timeOutTime);
        }
      }
    }
  }, [notifications, currentNotificationsIds, onRemoveNotification]);

  return (
    <div className={styles.wrapper}>
      <ul className={styles.notificationList}>
        <AnimatePresence initial={false}>
          {notifications.map((notification) => (
            <motion.li
              layout={true}
              key={notification.id}
              className={styles.notificationItem}
              initial={{ opacity: 0, y: -100 }}
              animate={{ opacity: 1, y: 0, transition: { duration: 0.2 } }}
              exit={{ opacity: 0, y: 100, transition: { duration: 0.2 } }}
            >
              {notification.notificationType === ADD_TO_CART_NOTIFICATION ? (
                <AddToCartNotification
                  headline={notification.headline}
                  body={notification.body}
                  onClose={() => onRemoveNotification(notification.id)}
                  setValue={setValue}
                  continueShoppingLink={notification.continueShoppingLink}
                />
              ) : (
                <Notification
                  headline={notification.headline}
                  body={notification.body}
                  notificationType={notification.notificationType}
                  onClose={() => onRemoveNotification(notification.id)}
                />
              )}
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
    </div>
  );
};

export default NotificationCenter;
