import styles from "./link.module.less";
import { type AnchorHTMLAttributes, type PropsWithChildren } from "react";
import { IContentfulLink } from "../../../types/contentful-types";
import { Link as GatsbyLink } from "gatsby-link";
import { multipleClassNames } from "@/core/helpers";

type CustomAnchorHTMLAttributes = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href" | "target">;

type LinkProps = {
  /** Link object from Contentful. Takes priority over `internalLink`/`externalLink`. Its `title` and `openInNewTab` are used when set; otherwise the props of the same name apply. */
  contentfulLink?: IContentfulLink;
  /** Path within the site, rendered with Gatsby's Link (client-side navigation). Used when no `contentfulLink` is given. */
  internalLink?: string;
  /** Full URL to another site, rendered as a plain anchor with `rel="noreferrer"`. Used when neither `contentfulLink` nor `internalLink` is given. */
  externalLink?: string;
  /** Link text when no `children` are passed, and the anchor's `title` attribute for external links. */
  title?: string;
  /** Opens the link in a new tab. Also makes an internal link render as a plain anchor instead of a Gatsby Link. Defaults to false. */
  openInNewTab?: boolean;
  className?: string;
} & CustomAnchorHTMLAttributes;

type BaseLinkProps = {
  to: string;
  title: string | undefined;
  openInNewTab: boolean;
  className?: string;
} & CustomAnchorHTMLAttributes;

const InternalLink = ({
  to,
  title,
  className,
  children,
  openInNewTab: _discard,
  ...props
}: PropsWithChildren<BaseLinkProps>) => {
  return (
    <GatsbyLink to={to} className={multipleClassNames(styles.link, className)} {...props}>
      {children ?? title}
    </GatsbyLink>
  );
};

const ExternalLink = ({ to, title, openInNewTab, className, children, ...props }: PropsWithChildren<BaseLinkProps>) => {
  return (
    <a
      href={to}
      title={title}
      target={openInNewTab ? "_blank" : ""}
      className={multipleClassNames(styles.link, className)}
      {...props}
      rel="noreferrer"
    >
      {children ?? title}
    </a>
  );
};

const extractLink = (
  contentfulLink: IContentfulLink | undefined,
  internalLink: string | undefined,
  externalLink: string | undefined,
): { to: string; isInternal: boolean } | null => {
  if (contentfulLink) {
    return extractLink(undefined, contentfulLink.internalLink?.slug, contentfulLink.externalUrl);
  }
  if (internalLink) {
    return { to: internalLink, isInternal: true };
  }
  if (externalLink) {
    return { to: externalLink, isInternal: false };
  }
  return null;
};

export const Link = ({
  contentfulLink,
  internalLink,
  externalLink,
  title,
  openInNewTab = false,
  className,
  children,
  ...props
}: PropsWithChildren<LinkProps>) => {
  const linkData = extractLink(contentfulLink, internalLink, externalLink);
  if (!linkData) {
    // Fallback to just rendering children
    return <>{children}</>;
  }

  const baseLinkProps: BaseLinkProps = {
    ...props,
    to: linkData.to,
    title: contentfulLink?.title ?? title,
    openInNewTab: contentfulLink?.openInNewTab ?? openInNewTab,
    className: className,
  };

  if (linkData.isInternal && !baseLinkProps.openInNewTab) {
    return <InternalLink {...baseLinkProps}>{children}</InternalLink>;
  }
  return <ExternalLink {...baseLinkProps}>{children}</ExternalLink>;
};
