import { PropsWithChildren, useEffect, useState } from "react";

const CONTENT_CONTAINER_ID = "content-container";

export const ContentContainer = ({ children }: PropsWithChildren) => {
  return <div id={CONTENT_CONTAINER_ID}>{children}</div>;
};

export const useContentContainerRef = () => {
  const [dialogRoot, setDialogRoot] = useState<HTMLElement>();

  useEffect(() => {
    const root = document.getElementById(CONTENT_CONTAINER_ID);
    if (!root) throw new Error("CONTENT_CONTAINER_ID not found. Forgot to add ContentContainer as a HOC??");
    setDialogRoot(root);
  }, []);

  return dialogRoot;
};
