import { useEffect, useState } from "react";
import { multipleClassNames } from "@/core/helpers";
import styles from "./modal-portal.module.less";

export const MODAL_PORTAL_ID = "modal-portal";

export const ModalPortal = ({ pageTheme }: { pageTheme?: string }) => {
  return (
    <div
      id={MODAL_PORTAL_ID}
      className={multipleClassNames(
        styles.modalPortal,
        pageTheme ? `page-theme page-theme-${pageTheme} ${pageTheme}` : "",
      )}
    />
  );
};

export const useModalPortal = () => {
  const [modalPortal, setModalPortal] = useState<HTMLElement>();

  useEffect(() => {
    const root = document.getElementById(MODAL_PORTAL_ID);
    setModalPortal(root ?? undefined);
  }, []);

  return modalPortal;
};
